const formattable = changed.filter((file) => FORMATTABLE.test(file));
if (formattable.length) {
  steps.push({
    name: "oxfmt",
    cmd: ["bun", "x", "oxfmt", "--check", "--no-error-on-unmatched-pattern", ...formattable],
  });
}
if (tests.size)
  steps.push({ name: "test", cmd: ["bun", "test", ...[...tests].map((t) => `./${t}`)] });
